<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_login();$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$departmentId=(int)($_GET['departamento_id']??0);$ids=visible_department_ids($db,$user);if($departmentId>0&&!user_is_global($user)&&!in_array($departmentId,$ids,true)){$db->close();json_response(['ok'=>true,'data'=>[]]);}$where=["u.estatus='ACTIVO'","ud.estatus='ACTIVO'"];if($departmentId>0)$where[]='ud.departamento_id='.(int)$departmentId;elseif(!user_is_global($user))$where[]='ud.departamento_id IN ('.($ids?implode(',',array_map('intval',$ids)):'0').')';$sql="SELECT DISTINCT u.usuario_id,CONCAT_WS(' ',u.nombre,u.apellido_paterno,u.apellido_materno) nombre,u.puesto,ud.departamento_id,r.nombre rol FROM usuario u JOIN usuario_departamento ud ON ud.usuario_id=u.usuario_id JOIN rol r ON r.rol_id=ud.rol_id WHERE ".implode(' AND ',$where)." ORDER BY nombre";$rs=$db->query($sql);$data=[];while($r=$rs->fetch_assoc()){$r['usuario_id']=(int)$r['usuario_id'];$r['departamento_id']=$r['departamento_id']!==null?(int)$r['departamento_id']:null;$data[]=$r;}$db->close();json_response(['ok'=>true,'data'=>$data]);
